pub unsafe extern "C" fn MPlayOpen(
    mut mplayInfo: *mut MusicPlayerInfo,
    mut tracks: *mut MusicPlayerTrack,
    mut trackCount: u8_0,
) {
    WasmMPlayInit(mplayInfo);
    if !mplayInfo.is_null() {
        let fresh0 = &raw mut (*if !mplayInfo.is_null() {
            mplayInfo
        } else {
            &raw mut gNativeMemory as *mut ::core::ffi::c_uchar as *mut MusicPlayerInfo
        })
            .tracks;
        fresh0.write_unaligned(tracks);
        (*if !mplayInfo.is_null() {
            mplayInfo
        } else {
            &raw mut gNativeMemory as *mut ::core::ffi::c_uchar as *mut MusicPlayerInfo
        })
            .trackCount = trackCount;
    }
}
